const ALL_EATERIES = RAW_EATERIES.map(row => {
  const [
    id, name, outlet, category, tag, badge, rating, reviews,
    cuisine, avgPrice, waitTime, timing, imgKey, description,
    mustTry, location, isFeatured, isTrending, lat, lng
  ] = row;

  return {
    id,
    name,
    outlet,
    category,
    tag,
    badge,
    rating,
    reviews,
    cuisine,
    avgPrice,
    waitTime,
    timing,
    image: IMAGES[imgKey] || IMAGES.finedine1,
    description,
    mustTry,
    location,
    isFeatured,
    isTrending,
    coordinates: { lat, lng }
  };
});

